<?php
declare(strict_types=1);
// Real API/SQL race; stop worker/controller in this disposable project first.
require __DIR__.'/../vendor/autoload.php';
use Shipping\{Database,Settings,Rules,Unit};
function check(bool $ok,string $name):void{if(!$ok)throw new RuntimeException($name);echo "PASS $name\n";}
function finalizeHandle():CurlHandle{$base=getenv('SHIPPING_URL')?:'http://shipping-api:8000';$c=curl_init($base.'/api/control/finalize');curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>'{}',CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Basic '.base64_encode('operator:shipping-smoke')]]);return $c;}
function finalizeCode():int{$c=finalizeHandle();curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return $code;}
$db=new Database(new Settings());$r=$db->transaction(fn($u)=>$u->run());$previous=$db->transaction(fn($u)=>$u->query('SELECT * FROM shipping_adapter_sessions WHERE run_id=?',[$r['id']])[0]??null);$session=$previous['session_id']??Rules::uuid4();
$db->transaction(function($u)use($r,$session){$u->run();$u->execute("UPDATE runs SET mode='helics',state='running' WHERE id=?",[$r['id']]);$u->execute("INSERT INTO shipping_adapter_sessions(run_id,epoch,session_id) VALUES (?,?,?) ON CONFLICT(run_id) DO UPDATE SET native_pending=true,native_state='initializing'",[$r['id'],$r['epoch'],$session]);});
try{check(finalizeCode()===409,'API rejects native initializing finalize');$pdo=$db->connect();$pdo->beginTransaction();$u=new Unit($pdo);$u->run();$u->execute("UPDATE shipping_adapter_sessions SET native_pending=true,native_state='executing' WHERE run_id=?",[$r['id']]);$c=finalizeHandle();$multi=curl_multi_init();curl_multi_add_handle($multi,$c);$active=0;for($n=0;$n<4;$n++){curl_multi_exec($multi,$active);usleep(30000);}check($active>0&&curl_getinfo($c,CURLINFO_RESPONSE_CODE)===0,'concurrent finalize waits for pending-intent run lock');$pdo->commit();do{curl_multi_exec($multi,$active);if($active)curl_multi_select($multi,.1);}while($active);check(curl_getinfo($c,CURLINFO_RESPONSE_CODE)===409,'committed native pending intent rejects waiting API finalize');curl_multi_remove_handle($multi,$c);curl_multi_close($multi);curl_close($c);
    $db->transaction(fn($u)=>$u->execute("UPDATE shipping_adapter_sessions SET native_pending=false,native_state='polling' WHERE run_id=?",[$r['id']]));check(finalizeCode()===409,'API rejects unsettled native receives');$db->transaction(fn($u)=>$u->execute("UPDATE shipping_adapter_sessions SET native_pending=false,native_state='executing' WHERE run_id=?",[$r['id']]));check(finalizeCode()===200,'settled native finalization intent accepted');$state=$db->transaction(fn($u)=>$u->one('SELECT native_pending,native_state FROM shipping_adapter_sessions WHERE run_id=?',[$r['id']]));check($state['native_pending']&&$state['native_state']==='finalizing','native finalize itself is fenced durably until transport settles');
}finally{$db->transaction(function($u)use($r,$previous,$session){$u->run();if($previous)$u->execute('UPDATE shipping_adapter_sessions SET native_pending=?,native_state=? WHERE run_id=?',[$previous['native_pending'],$previous['native_state'],$r['id']]);else $u->execute('DELETE FROM shipping_adapter_sessions WHERE session_id=?',[$session]);$u->execute('UPDATE runs SET mode=?,state=? WHERE id=?',[$r['mode'],$r['state'],$r['id']]);});}
